using GaoApp.Web.Services.Assistant;
using GaoApp.Web.Services.CustomerService;
using Xunit;
namespace GaoApp.Tests.Security;
public sealed class CustomerEvaluationTests:IDisposable
{
    private readonly string dir=Path.Combine(Path.GetTempPath(),"GaoEvaluationTests",Guid.NewGuid().ToString("N"));private readonly AssistantIntegrationTests.FixedClock clock=new();
    private CustomerServiceStore Store()=>new(new AssistantIntegrationTests.EnvironmentStub(dir),new AssistantIntegrationTests.Monitor<CustomerServiceOptions>(new(){DatabasePath="evaluation.db"}),clock);
    private static readonly CustomerStaff Manager=new(1,1,"TEST",true,true);
    private static HashSet<string> Empty()=>new(StringComparer.Ordinal);
    private static CustomerEvaluationInput Input(string query="TEST mặt hàng",string split="tune")=>new(Guid.NewGuid(),Guid.Empty,null,query,"exact",[1],split,"active",split=="holdout",true);
    private static SearchDocument[] Documents(int count=20)=>Enumerable.Range(1,count).Select(i=>new SearchDocument(i,i,"Mặt hàng TEST "+i,"SP-"+i.ToString("D3"),new(),[])).ToArray();
    private CustomerEvaluationCase[] Cases(int count=20)=>Enumerable.Range(1,count).Select(i=>new CustomerEvaluationCase(Guid.NewGuid(),"SP-"+i.ToString("D3"),"exact",[i],"holdout","active",Guid.NewGuid().ToString("N"),clock.Now,false)).ToArray();
    [Fact]public void Save_retry_and_edit_conflicts_preserve_one_versioned_case(){var s=Store();var input=Input();var c=s.SaveEvaluationCase(Manager,input,Empty());Assert.Equal(c.Id,s.SaveEvaluationCase(Manager,input,Empty()).Id);Assert.Single(s.EvaluationCases(Manager));Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,input with{Query="Khác"},Empty())).Status);var edit=input with{Id=c.Id,Version=c.Version,RequestId=Guid.NewGuid(),State="archived"};var next=s.SaveEvaluationCase(Manager,edit,Empty());Assert.NotEqual(c.Version,next.Version);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,edit with{RequestId=Guid.NewGuid()},Empty())).Status);}
    [Fact]public void Equivalent_queries_cannot_multiply_the_acceptance_sample(){var s=Store();s.SaveEvaluationCase(Manager,Input("Sữa TH 1L","holdout"),Empty());Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input("sua   th 1000ml","holdout"),Empty())).Status);}
    [Fact]public void Taught_case_cannot_be_promoted_even_with_a_different_phrase(){var s=Store();var c=s.SaveEvaluationCase(Manager,Input(),Empty());Assert.Equal(422,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input("Câu mới chưa dùng","holdout") with{Id=c.Id,Version=c.Version},Empty())).Status);}
    [Fact]public void Alias_history_marks_holdout_as_contaminated_before_and_after_recycle(){var s=Store();s.MarkEvaluationTeaching(Manager,"Tên riêng TEST");Assert.Equal(422,Assert.Throws<AssistantException>(()=>Store().SaveEvaluationCase(Manager,Input("Tên riêng TEST","holdout"),Empty())).Status);Assert.Equal(422,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input("Tên mới TEST","holdout"),new HashSet<string>(){AssistantCatalogSearch.Key("Tên mới TEST")})).Status);}
    [Fact]public void Invalid_cases_need_sanitization_independence_and_exact_ids(){var s=Store();Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input() with{Sanitized=false},Empty())).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input(split:"holdout") with{Independent=false},Empty())).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input() with{ExpectedVariantIds=[1,2]},Empty())).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input() with{Kind="not_found"},Empty())).Status);}
    [Theory][InlineData("0000012345678")][InlineData("SP-001")][InlineData("180ml")]
    public void Evaluation_accepts_identifiers_and_partial_questions_without_turning_them_into_aliases(string query){var c=Store().SaveEvaluationCase(Manager,Input(query),Empty());Assert.Equal(query,c.Query);}
    [Fact]public void Cases_are_scoped_and_limit_active_rows_before_unbounded_ranking(){var s=Store();for(var i=1;i<=100;i++)s.SaveEvaluationCase(Manager,Input("TEST mã "+i),Empty());Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input("TEST mã 101"),Empty())).Status);Assert.Empty(s.EvaluationCases(Manager with{StoreId=2}));var c=s.EvaluationCases(Manager)[0];Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager with{StoreId=2},Input("Sửa nơi khác") with{Id=c.Id,Version=c.Version},Empty())).Status);}
    [Fact]public void Missing_feedback_cannot_be_forged_as_the_source_of_a_case(){Assert.Equal(404,Assert.Throws<AssistantException>(()=>Store().SaveEvaluationCase(Manager,Input() with{FeedbackId=Guid.NewGuid()},Empty())).Status);}
    [Fact]public void Twenty_distinct_independent_correct_cases_pass_retrieval_gate(){var report=CustomerEvaluation.Run(Cases(),Documents(),"1",Empty(),clock,default);Assert.Equal("retrieval_passed",report.Gate);Assert.Equal(20,report.Holdout.Cases);Assert.Equal(1d,report.Holdout.Top1Accuracy);Assert.Equal(0,report.Holdout.Critical);Assert.Equal(64,report.CatalogRevision.Length);}
    [Fact]public void Small_or_taught_only_suites_never_claim_independent_acceptance(){var small=CustomerEvaluation.Run(Cases(19),Documents(),"1",Empty(),clock,default);Assert.Equal("insufficient_holdout",small.Gate);var cases=Cases();var taught=CustomerEvaluation.Run(cases,Documents(),"1",cases.Select(c=>AssistantCatalogSearch.Key(c.Query)).ToHashSet(),clock,default);Assert.Equal(0,taught.Holdout.Cases);Assert.Null(taught.Holdout.PassRate);Assert.Equal(20,taught.Tune.Cases);Assert.All(taught.Observations,c=>Assert.Equal("teaching_overlap",c.ExcludedFromHoldout));}
    [Fact]public void Critical_wrong_product_fails_even_when_overall_score_is_ninety_five_percent(){var cases=Cases();cases[0]=cases[0] with{ExpectedVariantIds=[2]};var report=CustomerEvaluation.Run(cases,Documents(),"1",Empty(),clock,default);Assert.Equal(.95,report.Holdout.PassRate);Assert.Equal(1,report.Holdout.Critical);Assert.Equal("needs_review",report.Gate);}
    [Fact]public void Removed_expected_products_are_failures_not_skipped_samples(){var cases=Cases(1);cases[0]=cases[0] with{ExpectedVariantIds=[999]};var report=CustomerEvaluation.Run(cases,Documents(),"1",Empty(),clock,default);Assert.False(Assert.Single(report.Observations).Passed);Assert.Equal(1,report.Holdout.Critical);}
    [Fact]public void Approved_aliases_require_confirmation_and_are_not_counted_as_unseen(){var docs=Documents(1);docs[0]=docs[0] with{Aliases=["tên riêng TEST"]};var c=Cases(1);c[0]=c[0] with{Query="tên riêng TEST",Kind="confirm"};var report=CustomerEvaluation.Run(c,docs,"1",Empty(),clock,default);Assert.True(Assert.Single(report.Observations).Passed);Assert.Equal(1,report.Tune.Cases);Assert.Equal(0,report.Holdout.Cases);}
    [Theory][InlineData("ambiguous",true)][InlineData("not_found",false)]
    public void Ambiguity_and_absent_product_expectations_are_evaluated_as_behavior(string kind,bool expected){var c=Cases(1);c[0]=c[0] with{Query="Mặt hàng TEST",Kind=kind,ExpectedVariantIds=kind=="not_found"?[]:[1,2]};var report=CustomerEvaluation.Run(c,Documents(),"1",Empty(),clock,default);Assert.Equal(expected,Assert.Single(report.Observations).Passed);}
    [Fact]public void Report_commit_fences_edits_and_new_teaching_during_the_run(){var s=Store();var c=s.SaveEvaluationCase(Manager,Input("SP-001","holdout"),Empty());var cases=s.EvaluationCases(Manager);var report=CustomerEvaluation.Run(cases,Documents(),"1",Empty(),clock,default);var input=new CustomerEvaluationRunInput(Guid.NewGuid(),CustomerEvaluation.SuiteVersion(cases));s.MarkEvaluationTeaching(Manager,c.Query);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationReport(Manager,input,report)).Status);Assert.Empty(s.EvaluationReports(Manager));s.SaveEvaluationCase(Manager,Input("SP-002","holdout"),Empty());Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.SaveEvaluationReport(Manager,input,report)).Status);}
    [Fact]public void Report_retry_is_durable_scoped_and_does_not_rerun_or_relabel_cases(){var s=Store();s.SaveEvaluationCase(Manager,Input("SP-001","holdout"),Empty());var cases=s.EvaluationCases(Manager);var report=CustomerEvaluation.Run(cases,Documents(),"1",Empty(),clock,default);var input=new CustomerEvaluationRunInput(Guid.NewGuid(),CustomerEvaluation.SuiteVersion(cases));s.SaveEvaluationReport(Manager,input,report);Assert.Equal(report.Id,Store().ReplayEvaluationRun(Manager,input)!.Id);Assert.Empty(s.EvaluationReports(Manager with{StoreId=2}));Assert.Equal(report.Id,s.SaveEvaluationReport(Manager,input,report with{Id=Guid.NewGuid()}).Id);clock.Now=clock.Now.AddDays(8);Assert.Empty(Store().EvaluationReports(Manager));Assert.Single(Store().EvaluationCases(Manager));}
    [Fact]public void Deleting_archived_cases_removes_associated_reports_without_erasing_teaching_history(){var s=Store();var create=Input("SP-001");var c=s.SaveEvaluationCase(Manager,create,Empty());var rows=s.EvaluationCases(Manager);var report=CustomerEvaluation.Run(rows,Documents(),"1",Empty(),clock,default);s.SaveEvaluationReport(Manager,new(Guid.NewGuid(),CustomerEvaluation.SuiteVersion(rows)),report);c=s.SaveEvaluationCase(Manager,Input("SP-001") with{Id=c.Id,Version=c.Version,State="archived"},Empty());var command=new CustomerEvaluationDelete(Guid.NewGuid(),c.Version);Assert.True(s.DeleteEvaluationCase(Manager,c.Id,command));Assert.True(Store().DeleteEvaluationCase(Manager,c.Id,command));Assert.Empty(s.EvaluationCases(Manager));Assert.Empty(s.EvaluationReports(Manager));Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,create,Empty())).Status);Assert.Equal(422,Assert.Throws<AssistantException>(()=>s.SaveEvaluationCase(Manager,Input("SP-001","holdout"),Empty())).Status);}
    public void Dispose(){if(Directory.Exists(dir))Directory.Delete(dir,true);}
}
